policy BakeryStockPolicy {
  allow read Ingredients(ingredient, on_hand, minimum, reorder_qty, supplier, unit_cost)
  allow supplier Ingredients.supplier
  limit order $250 per action
  limit order $1250 per day
}

program:
procedure BakeryReorder {
  about "Reorder ingredients below their minimum"
  policy BakeryStockPolicy
  sheet Ingredients "Ingredients" { ingredient: Text, on_hand: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every monday at 17:30

  let all = fetch Ingredients
  let low = filter all where on_hand < minimum
  for each i in low up to 5 {
    let cost = i.reorder_qty * i.unit_cost
