      notify owner "Reorder of {i.ingredient} would cost {cost}, over the $250 limit."
      skip
    }
    order "{i.reorder_qty} x {i.ingredient}" from i.supplier cost cost, ask owner first timeout 2 hours else skip
    log "ordered {i.ingredient}"
  }
}

