procedure PetgroomerRefunds {
  about "Handle refund requests within limits"
  policy PetgroomerRefundPolicy
  sheet RefundRequests "RefundRequests" { request_id: Text, owner: Text, phone: Phone, amount: Money, purchased: Date, status: Text }
  trigger when new row r in RefundRequests

  if days_between(r.purchased, today()) > 30 {
    notify owner "Refund request {r.request_id} is older than 30 days."
    stop "outside refund window"
  }
  if r.amount > $50.00 {
    notify owner "Refund request {r.request_id} is {r.amount}, over $50. Please review."
    stop "over refund limit"
  }
  if r.amount <= $10.00 {
    refund r.amount for r.request_id reason "refund request"
  } else {
    refund r.amount for r.request_id reason "refund request", ask owner first timeout 12 hours else stop "refund not approved"
  }
  update r set status = "refunded"
  let m = draft sms to r.phone: "Hi {r.owner default 'there'}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 12 hours else stop "message not approved"
  send ok
}

procedure RestaurantRefunds {
  about "Handle refund requests within limits"
  policy RestaurantRefundPolicy
  sheet RefundRequests "RefundRequests" { request_id: Text, guest: Text, phone: Phone, amount: Money, purchased: Date, status: Text }
  trigger when new row r in RefundRequests

  if days_between(r.purchased, today()) > 60 {
    notify owner "Refund request {r.request_id} is older than 60 days."
    stop "outside refund window"
  }
  if r.amount > $40.00 {
    notify owner "Refund request {r.request_id} is {r.amount}, over $40. Please review."
    stop "over refund limit"
  }
  refund r.amount for r.request_id reason "refund request", ask owner first timeout 6 hours else stop "refund not approved"
  update r set status = "refunded"
  let m = draft sms to r.phone: "Hi {r.guest default 'there'}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
  send ok
}

