program:
procedure RetailReorder {
  about "Reorder products below their minimum"
  policy RetailStockPolicy
  sheet Stock "Stock" { product: Text, qty: Number, min_qty: Number, reorder_qty: Number, vendor: Text, cost: Money }
  trigger every day at 16:00

  let all = fetch Stock
  let low = filter all where qty < min_qty
  for each i in low up to 4 {
    let cost = i.reorder_qty * i.cost
    if cost > $100.00 {
      notify owner "Reorder of {i.product} would cost {cost}, over the $100 limit."
