procedure BikeshopRefunds {
  about "Handle refund requests within limits"
  policy BikeshopRefundPolicy
  sheet RefundRequests "RefundRequests" { request_id: Text, customer: Text, phone: Phone, amount: Money, purchased: Date, status: Text }
  trigger when new row r in RefundRequests

  if days_between(r.purchased, today()) > 14 {
    notify owner "Refund request {r.request_id} is older than 14 days."
    stop "outside refund window"
  }
  if r.amount > $40.00 {
    notify owner "Refund request {r.request_id} is {r.amount}, over $40. Please review."
    stop "over refund limit"
  }
  if r.amount <= $15.00 {
    refund r.amount for r.request_id reason "refund request"
  } else {
    refund r.amount for r.request_id reason "refund request", ask owner first timeout 2 hours else stop "refund not approved"
  }
  update r set status = "refunded"
  let m = draft sms to r.phone: "Hi {r.customer}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 2 hours else stop "message not approved"
  send ok
}

